function storageService($window){return{set:function(key,value){return $window.localStorage[key]=value},get:function(key,defaultValue){return $window.localStorage[key]||defaultValue},setObject:function(key,value){$window.localStorage[key]=JSON.stringify(value)},getObject:function(key){return JSON.parse($window.localStorage[key]||"{}")},askToSaveDetailDoc:async function(name,valueStorage){let{isConfirmed:isConfirmed,value:value}=await Swal.fire({title:"<small>Apartar Documento</small>",input:"text",inputAttributes:{autocapitalize:"off"},showCancelButton:!0,confirmButtonText:"Apartar",cancelButtonText:"No, cancelar",inputValidator:value=>value?Object.keys(this.getObject(name)).length>0&&this.getObject(name)[value]?"Ya existe Documento Apartado con esta descripción":void 0:"Ingrese la descripción!"});if(isConfirmed){if(Object.keys(this.getObject(name)).length>0){let dataInvoiceDetail=this.getObject(name);dataInvoiceDetail[value]=JSON.stringify(valueStorage),this.setObject(name,dataInvoiceDetail),toastr.success("Documento Apartado Correctamente")}if(0===Object.keys(this.getObject(name)).length){let objSave={[value]:JSON.stringify(valueStorage)};this.setObject(name,objSave),toastr.success("Documento Apartado Correctamente")}}return isConfirmed},restoreInvoiceDetail:async function(name){let dataInvoiceDetail=this.getObject(name);const{isConfirmed:isConfirmed,value:value}=await Swal.fire({title:"<small>Recuperar Detalle del Documento</small>",input:"select",inputOptions:Object.keys(dataInvoiceDetail).reduce((obj,cur)=>({...obj,[cur]:cur}),{}),inputPlaceholder:"Seleccionar el documento",showCancelButton:!0,confirmButtonText:"Recuperar detalle",cancelButtonText:"No, cancelar",allowEscapeKey:!1,allowOutsideClick:!1,inputValidator:value=>new Promise(resolve=>{value?resolve():resolve("Seleccione la opción :)")})});return{isConfirmed:isConfirmed,value:value,dataInvoiceDetail:dataInvoiceDetail}}}}app.factory("storageService",storageService),storageService.$inject=["$window"];